import{_ as a,c as e,o,a2 as r}from"./chunks/framework.CHomSxuB.js";const g=JSON.parse('{"title":"4. 分歧低吸：黄金坑还是接飞刀（V0.6）","description":"","frontmatter":{},"headers":[],"relativePath":"A股量化验证/4-分歧低吸.md","filePath":"A股量化验证/4-分歧低吸.md"}'),d={name:"A股量化验证/4-分歧低吸.md"};function n(l,t,s,h,i,p){return o(),e("div",null,t[0]||(t[0]=[r('<h1 id="_4-分歧低吸-黄金坑还是接飞刀-v0-6" tabindex="-1">4. 分歧低吸：黄金坑还是接飞刀（V0.6） <a class="header-anchor" href="#_4-分歧低吸-黄金坑还是接飞刀-v0-6" aria-label="Permalink to &quot;4. 分歧低吸：黄金坑还是接飞刀（V0.6）&quot;">​</a></h1><blockquote><p>结论：<strong>&quot;分歧低吸&quot;叙事被证伪——次日低开的首板是弱势确认，不是黄金坑</strong> —— <code>NO_EDGE</code> 卷宗：<code>v0.6_firstboard_dip_prereg.md</code>（协议+裁决同卷）</p></blockquote><h2 id="故事" tabindex="-1">故事 <a class="header-anchor" href="#故事" aria-label="Permalink to &quot;故事&quot;">​</a></h2><p>首板（非一字）个股次日常因隔夜获利盘<strong>低开</strong>。流行叙事：低开是&quot;主线未退潮的黄金坑&quot;， 在低开区间买入应显著优于 Step 1 的无差别买入——即&quot;低开择时过滤器&quot;能提供增量 edge。</p><h2 id="协议-v0-6-冻结-2026-08-19-全量-243-天-只跑一次不调参" tabindex="-1">协议（V0.6 冻结，2026-08-19 全量 243 天，只跑一次不调参） <a class="header-anchor" href="#协议-v0-6-冻结-2026-08-19-全量-243-天-只跑一次不调参" aria-label="Permalink to &quot;协议（V0.6 冻结，2026-08-19 全量 243 天，只跑一次不调参）&quot;">​</a></h2><ul><li>候选：首板非一字全样本 7,606</li><li>过滤组 D2 = 次日低开（D2 开盘 &lt; D0 收盘）n=1,475</li><li>基线 S1 = 无差别首板 n=7,151</li><li>三重检验：H1 过滤组 Ev &gt; 基线；H2 日内反弹胜率 &gt; 52%；H3 尾部缓冲 p10 优于基线</li><li>本线 excess（vs 中证1000）预注册声明<strong>不计算</strong>，只报原始 Ev（保持离线纯粹性）</li></ul><h2 id="实测" tabindex="-1">实测 <a class="header-anchor" href="#实测" aria-label="Permalink to &quot;实测&quot;">​</a></h2><table tabindex="0"><thead><tr><th>口径</th><th>D2 低开组 Ev</th><th>D2 胜率</th><th>S1 无差别 Ev</th><th>S1 胜率</th></tr></thead><tbody><tr><td>Paper 日内反弹</td><td>+0.23%</td><td><strong>45.8%</strong></td><td>+0.13%</td><td>49.7%</td></tr><tr><td>T1 (D1→D2 可交易)</td><td><strong>−0.02%</strong> (p=0.53)</td><td>—</td><td><strong>+0.48%</strong> (p=0.99)</td><td>—</td></tr></tbody></table><table tabindex="0"><thead><tr><th>假设</th><th>实测</th><th>结果</th></tr></thead><tbody><tr><td>H1 低开组 Ev 优于无差别</td><td>T1 −0.02% vs +0.48%，<strong>显著更差</strong></td><td>❌</td></tr><tr><td>H2 日内反弹胜率 &gt;52%</td><td>45.8% &lt; 52%（p=0.86）</td><td>❌</td></tr><tr><td>H3 尾部缓冲</td><td>p10_D2=−8.39% vs p10_S1=−8.04%，<strong>左尾更差</strong></td><td>❌</td></tr></tbody></table><p>FDR：{H1:0.012, H2:0.012}（低开组差得&quot;显著&quot;）。</p><h2 id="裁决-no-edge-方向性反转" tabindex="-1">裁决：<code>NO_EDGE</code>（方向性反转） <a class="header-anchor" href="#裁决-no-edge-方向性反转" aria-label="Permalink to &quot;裁决：`NO_EDGE`（方向性反转）&quot;">​</a></h2><p>三条假设全 FAIL，且<strong>方向反转</strong>：</p><ul><li>低开不是&quot;6 个点安全垫&quot;，而是<strong>弱势确认</strong>——低开股次日多数继续跌（胜率仅 45.8%）；</li><li>低开区间买入 = <strong>接飞刀</strong>，下行尾部比无差别更差（p10 −8.39% vs −8.04%）；</li><li>与 Step 5 连板接力&quot;日收益近似 iid&quot;一脉相承：<strong>短线择时/排序信号在本宇宙无分辨力</strong>。</li></ul><h2 id="附带观察-非本轮假设-需独立预注册才可采信" tabindex="-1">附带观察（非本轮假设，需独立预注册才可采信） <a class="header-anchor" href="#附带观察-非本轮假设-需独立预注册才可采信" aria-label="Permalink to &quot;附带观察（非本轮假设，需独立预注册才可采信）&quot;">​</a></h2><p>S1 无差别首板次日 T1 Ev = +0.48%（p=0.99 显著为正），但净摩擦后约 +0.13%， <strong>薄且高换手</strong>（~29 笔/日）。属&quot;涨停次日惯性&quot;已知现象的弱印证——这就是 Step 1 主线的 原始信号，但利润厚度远低于回测给人的印象，容量与摩擦是真实约束。</p><h2 id="处置" tabindex="-1">处置 <a class="header-anchor" href="#处置" aria-label="Permalink to &quot;处置&quot;">​</a></h2><p>❌ 首板次日分歧低吸（低开区间过滤）作为 edge 来源，封存。 Step 4 前向追踪不受影响，仍在跑。</p><hr><p><strong>验证线汇总导航</strong>：<a href="/A股量化验证/">返回 A股量化验证 首页</a> · <a href="/A股量化验证/3-连板接力与情绪闸门.html">上一线：连板接力与情绪闸门</a> · <a href="/A股量化验证/5-龙虎榜机构席位.html">下一线：龙虎榜机构席位</a></p>',19)]))}const _=a(d,[["render",n]]);export{g as __pageData,_ as default};
